// serveMetadata exercises both halves of MetadataSourcePlugin over a real
// in-process gRPC connection: GRPCServer registers the metadata service on a
// bufconn-backed server (and is asserted to register the right service), then
// GRPCClient returns the dispensed MetadataSource client. No test doubles sit
// between the server adapter (metadataServer) and the client adapter
// (metadataGRPC) -- the seam-S9 contract.
func serveMetadata(t *testing.T, impl MetadataSource) MetadataSource {
	t.Helper()
	lis := bufconn.Listen(1024 * 1024)
	srv := grpc.NewServer()
	plug := &MetadataSourcePlugin{Impl: impl}
	if err := plug.GRPCServer(nil, srv); err != nil { // exercises GRPCServer
		t.Fatalf("GRPCServer: %v", err)
	}
	if _, ok := srv.GetServiceInfo()[metadataServiceName]; !ok {
		t.Fatalf("GRPCServer did not register %q", metadataServiceName)
	}
	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(srv.Stop)

	conn, err := grpc.DialContext(context.Background(), "bufnet",
		grpc.WithContextDialer(func(context.Context, string) (net.Conn, error) { return lis.Dial() }),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	if err != nil {
		t.Fatalf("Dial: %v", err)
	}
	t.Cleanup(func() { _ = conn.Close() })

	raw, err := plug.GRPCClient(context.Background(), nil, conn) // exercises GRPCClient
	if err != nil {
		t.Fatalf("GRPCClient: %v", err)
	}
	ms, ok := raw.(MetadataSource)
	if !ok {
		t.Fatalf("GRPCClient returned %T, want sdk.MetadataSource", raw)
	}
	return ms
}

